const guestParams={adults:searchParams.get('adults')||'1',children:searchParams.get('children')||'0',rooms:searchParams.get('rooms')||'1'};
const resultsGuestLabel=document.querySelector('.search-guests');
const resultsPlural=(value,one,few,many)=>{const mod10=value%10,mod100=value%100;return mod10===1&&mod100!==11?one:mod10>=2&&mod10<=4&&(mod100<12||mod100>14)?few:many};
const updateResultsGuests=()=>{const adults=Number(guestParams.adults),children=Number(guestParams.children);resultsGuestLabel.innerHTML=`${adults} ${resultsPlural(adults,'взрослый','взрослых','взрослых')}${children?` · ${children} ${resultsPlural(children,'ребёнок','ребёнка','детей')}`:''} <img src="assets/arrow-down-fill-16.svg" alt="">`;document.querySelectorAll('.results-guests-popover [data-kind]').forEach(row=>{const value=Number(guestParams[row.dataset.kind]);row.querySelector('output').textContent=String(value);row.querySelector('[data-result-step="-1"]').disabled=value<=(row.dataset.kind==='children'?0:1);row.querySelector('[data-result-step="1"]').disabled=value>=9});document.querySelectorAll('.hotel-title a').forEach(link=>{const url=new URL(link.href,location.href);url.searchParams.set('adults',guestParams.adults);url.searchParams.set('children',guestParams.children);url.searchParams.set('rooms',guestParams.rooms);link.href=url.href});const nights=document.querySelector('.search-date small')?.textContent.replace('·','').trim()||'1 ночь';const guests=adults+children;document.querySelectorAll('.map-offer-stay').forEach(stay=>{stay.textContent=`За ${nights} для ${guests} ${resultsPlural(guests,'гостя','гостей','гостей')}`})};
