 const mapHotelPopup=mapStage.querySelector('.map-hotel-popup');let selectedMapMarker=null,mapZoom=1;const mapPriceButtons=[...mapStage.querySelectorAll('.map-prices button')].map((button,index)=>({button,x:parseFloat(button.style.getPropertyValue('--x')),y:parseFloat(button.style.getPropertyValue('--y')),name:mapPopupData[index]})),positionMapPopup=marker=>{mapHotelPopup.style.setProperty('--popup-x',marker.style.getPropertyValue('--x'));mapHotelPopup.style.setProperty('--popup-y',marker.style.getPropertyValue('--y'))},updateMapZoom=()=>{mapStage.style.setProperty('--map-zoom',mapZoom);mapStage.style.setProperty('--radius-scale',mapZoom*.8);mapPriceButtons.forEach(({button,x,y})=>{button.style.setProperty('--x',`${50+(x-50)*mapZoom}%`);button.style.setProperty('--y',`${50+(y-50)*mapZoom}%`)});if(selectedMapMarker)positionMapPopup(selectedMapMarker);mapStage.querySelector('[data-map-zoom="1"]').disabled=mapZoom>=1.6;mapStage.querySelector('[data-map-zoom="-1"]').disabled=mapZoom<=1};updateMapZoom();mapStage.querySelector('.map-zoom').addEventListener('click',event=>{const button=event.target.closest('[data-map-zoom]');if(!button||button.disabled)return;mapZoom=Math.max(1,Math.min(1.6,Math.round((mapZoom+Number(button.dataset.mapZoom)*.15)*100)/100));updateMapZoom()});
