 mapStage.querySelector('.map-prices').addEventListener('click',event=>{const marker=event.target.closest('button');if(!marker)return;selectedMapMarker=marker;mapStage.querySelectorAll('.map-prices button').forEach(button=>button.classList.toggle('is-active',button===marker));const item=mapPriceButtons.find(entry=>entry.button===marker);mapHotelPopup.querySelector('strong').textContent=item.name;mapHotelPopup.querySelector('b').textContent=`от ${marker.textContent.trim()}`;mapHotelPopup.querySelector('a').href=`hotel.html?${new URLSearchParams({hotel:item.name,adults:guestParams.adults,children:guestParams.children,rooms:guestParams.rooms})}`;positionMapPopup(marker);mapHotelPopup.hidden=false});
